const bcrypt = require('bcrypt');
const jwt = require('jsonwebtoken');
const { User } = require('../models');
const ApiError = require('../utils/ApiError');

const SALT_ROUNDS = 12;
const ACCESS_TOKEN_EXPIRY = '15m';
const REFRESH_TOKEN_EXPIRY = '7d';

exports.register = async ({ email, password, firstName, lastName }) =&gt; {
  const existingUser = await User.findOne({ where: { email } });
  if (existingUser) {
    throw new ApiError(409, 'Email already registered');
  }

  const hashedPassword = await bcrypt.hash(password, SALT_ROUNDS);
  const user = await User.create({
    email,
    password: hashedPassword,
    first_name: firstName,
    last_name: lastName,
  });

  const tokens = generateTokens(user);
  return { user: sanitizeUser(user), ...tokens };
};

exports.login = async ({ email, password }) =&gt; {
  const user = await User.findOne({ where: { email } });
  if (!user || !(await bcrypt.compare(password, user.password))) {
    throw new ApiError(401, 'Invalid email or password');
  }

  const tokens = generateTokens(user);
  return { user: sanitizeUser(user), ...tokens };
};

function generateTokens(user) {
  const accessToken = jwt.sign(
    { userId: user.id, email: user.email, role: user.role },
    process.env.JWT_SECRET,
    { expiresIn: ACCESS_TOKEN_EXPIRY }
  );

  const refreshToken = jwt.sign(
    { userId: user.id, tokenType: 'refresh' },
    process.env.JWT_REFRESH_SECRET,
    { expiresIn: REFRESH_TOKEN_EXPIRY }
  );

  return { accessToken, refreshToken };
}

function sanitizeUser(user) {
  const { password, ...userData } = user.toJSON();
  return userData;
}</code></pre><p>تتحقق البرامج الوسيطة للمصادقة من الرموز المميزة على المسارات المحمية:</p><pre><code>// src/middleware/auth.js
const jwt = require('jsonwebtoken');
const ApiError = require('../utils/ApiError');

exports.authenticate = (req, res, next) =&gt; {
  const authHeader = req.headers.authorization;
  if (!authHeader?.startsWith('Bearer ')) {
    throw new ApiError(401, 'Access token required');
  }

  const token = authHeader.split(' ')[1];
  try {
    const decoded = jwt.verify(token, process.env.JWT_SECRET);
    req.user = decoded;
    next();
  } catch (error) {
    if (error.name === 'TokenExpiredError') {
      throw new ApiError(401, 'Access token expired');
    }
    throw new ApiError(401, 'Invalid access token');
  }
};

exports.authorize = (...roles) =&gt; {
  return (req, res, next) =&gt; {
    if (!roles.includes(req.user.role)) {
      throw new ApiError(403, 'Insufficient permissions');
    }
    next();
  };
};</code></pre><h2>التحقق من صحة الإدخال باستخدام Joi</h2><p>التحقق من صحة جميع البيانات الواردة قبل أن تصل إلى منطق عملك. يوفر Joi مكتبة تحقق قوية قائمة على المخطط.</p><pre><code>// src/validators/product.js
const Joi = require('joi');

exports.createProductSchema = Joi.object({
  name: Joi.string().min(2).max(255).required(),
  description: Joi.string().max(5000).optional(),
  price: Joi.number().positive().precision(2).required(),
  sku: Joi.string().alphanum().max(100).required(),
  stock_quantity: Joi.number().integer().min(0).default(0),
  category_id: Joi.string().uuid().required(),
  tags: Joi.array().items(Joi.string().uuid()).optional(),
  is_active: Joi.boolean().default(true),
});

exports.updateProductSchema = Joi.object({
  name: Joi.string().min(2).max(255),
  description: Joi.string().max(5000).allow(null),
  price: Joi.number().positive().precision(2),
  stock_quantity: Joi.number().integer().min(0),
  category_id: Joi.string().uuid(),
  is_active: Joi.boolean(),
}).min(1);

// src/middleware/validator.js
exports.validate = (schema) =&gt; {
  return (req, res, next) =&gt; {
    const { error, value } = schema.validate(req.body, {
      abortEarly: false,
      stripUnknown: true,
    });

    if (error) {
      const errors = error.details.map(detail =&gt; ({
        field: detail.path.join('.'),
        message: detail.message,
      }));
      return res.status(400).json({
        success: false,
        message: 'Validation failed',
        errors,
      });
    }

    req.body = value;
    next();
  };
};</code></pre><h2>معالجة الأخطاء للبرامج الوسيطة</h2><p>تضمن معالجة الأخطاء المركزية استجابات متسقة للأخطاء وتمنع تسرب المعلومات الحساسة إلى العملاء.</p><pre><code>// src/utils/ApiError.js
class ApiError extends Error {
  constructor(statusCode, message, errors = []) {
    super(message);
    this.statusCode = statusCode;
    this.errors = errors;
    this.isOperational = true;
    Error.captureStackTrace(this, this.constructor);
  }
}

module.exports = ApiError;

// src/utils/asyncHandler.js
exports.asyncHandler = (fn) =&gt; (req, res, next) =&gt; {
  Promise.resolve(fn(req, res, next)).catch(next);
};

// src/middleware/errorHandler.js
const logger = require('../config/logger');

exports.errorHandler = (err, req, res, next) =&gt; {
  let statusCode = err.statusCode || 500;
  let message = err.message || 'Internal Server Error';

  // Sequelize validation errors
  if (err.name === 'SequelizeValidationError') {
    statusCode = 400;
    message = 'Validation error';
  }

  // Sequelize unique constraint
  if (err.name === 'SequelizeUniqueConstraintError') {
    statusCode = 409;
    message = 'Resource already exists';
  }

  // Log server errors
  if (statusCode >= 500) {
    logger.error({
      message: err.message,
      stack: err.stack,
      url: req.originalUrl,
      method: req.method,
      ip: req.ip,
    });
  }

  res.status(statusCode).json({
    success: false,
    message,
    ...(process.env.NODE_ENV === 'development' &amp;&amp; { stack: err.stack }),
    ...(err.errors?.length &amp;&amp; { errors: err.errors }),
  });
};</code></pre><h2>تحسين الاستعلام وفهرسته</h2><p>تعد استعلامات قاعدة البيانات الفعالة أمرًا بالغ الأهمية لأداء الواجهة الخلفية. اتبع هذه الاستراتيجيات لإبقاء استعلامات MySQL الخاصة بك سريعة.</p><ul><li><strong>استخدم الفهارس على الأعمدة التي يتم الاستعلام عنها بشكل متكرر</strong>- أضف فهارس على الأعمدة المستخدمة في عبارات WHERE وشروط JOIN وعبارات ORDER BY. يجب أن تتبع الفهارس المركبة قاعدة البادئة الموجودة في أقصى اليسار.</li><li><strong>تجنب التحديد *</strong>- حدد دائمًا الأعمدة التي تحتاجها. وهذا يقلل من نقل البيانات ويسمح لـ MySQL باستخدام فهارس التغطية.</li><li><strong>استخدم EXPLAIN لتحليل الاستعلامات</strong>- قم بتشغيل<code>EXPLAIN</code>قبل استعلاماتك لفهم خطة التنفيذ. ابحث عن عمليات فحص الجدول الكامل وعمليات فرز الملفات والجداول المؤقتة.</li><li><strong>تحسين ترقيم الصفحات</strong>- بالنسبة لمجموعات البيانات الكبيرة، استخدم ترقيم الصفحات المستند إلى المؤشر (ترقيم الصفحات لمجموعة المفاتيح) بدلاً من OFFSET، الذي يصبح بطيئًا عند ارتفاع أرقام الصفحات.</li></ul><pre><code>// Inefficient OFFSET pagination
